-- ── FOCUS WINDOWS (Super + Arrow) ────────────────────────
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.bind("SUPER + left", hl.dsp.focus({ direction = "left" }))
hl.bind("SUPER + right", hl.dsp.focus({ direction = "right" }))
hl.bind("SUPER + up", hl.dsp.focus({ direction = "up" }))
hl.bind("SUPER + down", hl.dsp.focus({ direction = "down" }))

-- ── MOVE WINDOWS (Super + Shift + Arrow) ─────────────────
hl.bind("SUPER + SHIFT + left", hl.dsp.window.move({ direction = "l" }))
hl.bind("SUPER + SHIFT + right", hl.dsp.window.move({ direction = "r" }))
hl.bind("SUPER + SHIFT + up", hl.dsp.window.move({ direction = "u" }))
hl.bind("SUPER + SHIFT + down", hl.dsp.window.move({ direction = "d" }))

-- ── RESIZE (Super + Ctrl + Arrow) ────────────────────────
hl.bind("SUPER + CTRL + left", hl.dsp.window.resize({ x = -100, y = 0, relative = true }))
hl.bind("SUPER + CTRL + right", hl.dsp.window.resize({ x = 100, y = 0, relative = true }))
hl.bind("SUPER + CTRL + up", hl.dsp.window.resize({ x = 0, y = -100, relative = true }))
hl.bind("SUPER + CTRL + down", hl.dsp.window.resize({ x = 0, y = 100, relative = true }))

-- ── SUPER + DRAG (KDE style) ─────────────────────────────
hl.bind("SUPER + mouse:272", hl.dsp.window.drag())
hl.bind("SUPER + mouse:273", hl.dsp.window.resize())

-- Keybinds
hl.bind("Print", hl.dsp.exec_cmd("grim -g \"$(slurp)\" - | swappy -f -"))
hl.bind("SUPER + T", hl.dsp.exec_cmd("kitty"))
hl.bind("SUPER + C", hl.dsp.exec_cmd("kitty --title \"Claude Code\" bash -c \"claude; exec bash\""))
hl.bind("SUPER + E", hl.dsp.exec_cmd("dolphin"))
-- The launcher: the island's Search panel (quickshell/SearchPanel.qml).
-- A global shortcut, not toggle-search.sh: the script's `qs ipc` took
-- ~65 ms to arrive, and letters typed in that time went to the window
-- underneath. See the GlobalShortcut in quickshell/shell.qml.
hl.bind("SUPER + S", hl.dsp.global("quickshell:search"))
hl.bind("SUPER + Q", hl.dsp.window.close())
hl.bind("SUPER + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
hl.bind("SUPER + D", hl.dsp.exec_cmd("/usr/bin/discord"))
hl.bind("SUPER + ALT + L", hl.dsp.exec_cmd("hyprlock"))
-- Re-apply the display layout by hand. You should never need this --
-- conf/monitors.sh does it at startup and on every hotplug -- but it is
-- the replacement for "type kanshi in a terminal" if a monitor ever
-- comes up wrong.
hl.bind("SUPER + SHIFT + M", hl.dsp.exec_cmd("~/.config/hypr/conf/monitors.sh apply"))
-- Session menu (sized to whichever monitor you are on). P for power, to
-- sit with the panels' Super+Shift letters below; it was Super+Shift+E.
hl.bind("SUPER + SHIFT + P", hl.dsp.exec_cmd("~/.config/hypr/conf/power-menu.sh"))
-- Same launcher on the old key. rofi-launcher.sh is left in place: it
-- still works, and the environment block at the top of it is the
-- reference copy that apps.py's launch path was built from.
hl.bind("SUPER + R", hl.dsp.global("quickshell:search"))
-- ── The panels, one letter each (2026-10-06) ─────────────────────────
-- Super+Shift and the panel's first letter (A for audio: Super+Shift+S
-- is Search). Global shortcuts like Super+S, for the reason over the
-- GlobalShortcuts in quickshell/shell.qml. The same key again closes the
-- panel; another panel's key switches to it.
hl.bind("SUPER + SHIFT + S", hl.dsp.global("quickshell:search"))
hl.bind("SUPER + SHIFT + W", hl.dsp.global("quickshell:wifi"))
hl.bind("SUPER + SHIFT + B", hl.dsp.global("quickshell:bluetooth"))
hl.bind("SUPER + SHIFT + A", hl.dsp.global("quickshell:sound"))
hl.bind("SUPER + SHIFT + C", hl.dsp.global("quickshell:calendar"))
hl.bind("SUPER + B", hl.dsp.exec_cmd("brave"))
-- ── The bar's density, from the keyboard ─────────────────────────────
-- The corner handles are the pointer control; this is their twin. Every
-- pointer control on this desktop has one, because a control you can
-- only reach with the pointer is a control you cannot reach when the
-- pointer is the thing that is broken.
--
-- ALT + B, not SUPER + B: Super+B has been brave for longer than this
-- bar has existed, and the bar is the newcomer. It was SHIFT + B until
-- that went to the Bluetooth panel above (2026-10-06).
--
--   compact -> normal -> full -> compact
hl.bind("SUPER + ALT + B", hl.dsp.exec_cmd("qs ipc call bar cycle"))
-- ── Panic button for the popups ──────────────────────────────────────
-- Kills and restarts eww, and drops any submap. For the one failure that
-- leaves you with no other way in: a leftover layer surface holding the
-- pointer (and sometimes the keyboard) with nothing visible on screen.
-- A Hyprland bind still fires in that state -- the compositor sees the
-- key before any client does. See eww/scripts/eww-reset.sh.
hl.bind("SUPER + SHIFT + R", hl.dsp.exec_cmd("~/.config/eww/scripts/eww-reset.sh"))
-- ── Panic button for the Quickshell bar ──────────────────────────────
-- The same failure, one layer up. The bar is ONE PanelWindow, mapped at
-- login, as tall as the tallest state it can reach and never resized --
-- that is forced, because Quickshell cannot animate a window's size. So
-- there is a full-height invisible surface over the output at all times,
-- and the window's `mask` is the only thing stopping it swallowing every
-- click. If the mask is ever wrong the desktop looks frozen while
-- showing nothing; this is the one keystroke that gets you out, and the
-- compositor sees it before any client does.
--
-- Bound BEFORE the bar was written, deliberately. It is cheap now and it
-- is unreachable later, when you would need it.
-- Both names, because they are two binaries: /usr/bin/quickshell and
-- /usr/bin/qs, and the process's `comm` is whichever one was invoked.
-- The first version of this bind said `pkill -x quickshell` only, and
-- it matched NOTHING against a bar started as `qs` -- a panic button
-- that silently does nothing is worse than no panic button, because
-- you press it and conclude the machine is dead rather than the bind.
-- Caught by running pgrep against a live bar, not by reading this line.
hl.bind("SUPER + SHIFT + Q", hl.dsp.exec_cmd("pkill -x quickshell; pkill -x qs"))
hl.bind("SUPER + Space", hl.dsp.window.float({ action = "toggle" }))
-- Switch workspaces
hl.bind("SUPER + 1", hl.dsp.focus({ workspace = 1 }))
hl.bind("SUPER + 2", hl.dsp.focus({ workspace = 2 }))
hl.bind("SUPER + 3", hl.dsp.focus({ workspace = 3 }))
hl.bind("SUPER + 4", hl.dsp.focus({ workspace = 4 }))
hl.bind("SUPER + 5", hl.dsp.focus({ workspace = 5 }))
-- Cycle between active workspaces
hl.bind("SUPER + Tab", hl.dsp.focus({ workspace = "m+1" }))
hl.bind("SUPER + SHIFT + Tab", hl.dsp.focus({ workspace = "m-1" }))

-- Move windows
hl.bind("SUPER + SHIFT + 1", hl.dsp.window.move({ workspace = 1 }))
hl.bind("SUPER + SHIFT + 2", hl.dsp.window.move({ workspace = 2 }))
hl.bind("SUPER + SHIFT + 3", hl.dsp.window.move({ workspace = 3 }))
hl.bind("SUPER + SHIFT + 4", hl.dsp.window.move({ workspace = 4 }))
hl.bind("SUPER + SHIFT + 5", hl.dsp.window.move({ workspace = 5 }))

-- Eww popup submap — Escape closes panels (only active while a popup is open)
-- A SUBMAP REPLACES THE KEYMAP. It does not add to it: while one is
-- active, EVERY bind outside it is dead, including the panic button.
-- That is fine for a modal popup -- Escape is the way out and it is
-- right here -- but the one bind that must survive any state is the one
-- that recovers a broken state, so it is repeated inside the submap.
hl.define_submap("eww-popup", function()
    hl.bind("Escape", hl.dsp.exec_cmd("~/.config/eww/scripts/close-popups.sh"))
    hl.bind("Escape", hl.dsp.submap("reset"))
    hl.bind("SUPER + SHIFT + R", hl.dsp.exec_cmd("~/.config/eww/scripts/eww-reset.sh"))
    hl.bind("SUPER + SHIFT + R", hl.dsp.submap("reset"))
end)

-- The launcher's `eww-search` submap (Up/Down, Alt+1…6, Escape) went with
-- eww's search-panel on 2026-09-16. Search is quickshell/SearchPanel.qml and
-- handles its own keys; Super+S above is a global shortcut into it.

-- Media / volume keys (K400 Plus)
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1.0 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { locked = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })
